'use strict';
// ===================== Sample semester (demo data, every record tagged demo: true) =====================
function loadSample() {
  if (S.classes.some((c) => c.demo)) return toast('Sample data is already loaded');
  let seed = 20261119; const rnd = () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const t = today(), D = (n) => addDays(t, n), demo = { demo: true };
  const k = (name, weight) => ({ id: uid('k'), name, weight });
  const C = [
    { name: 'AP Biology', teacher: 'Ms. Rivera', room: 'Sci 204', color: '#34c38f', level: 'ap', goal: 90, cats: [k('Tests', 40), k('Quizzes', 20), k('Labs', 20), k('Homework', 20)], sched: [{ days: [1, 3, 5], start: '08:00', end: '08:50' }], skill: 0.86 },
    { name: 'Algebra 2 Honors', teacher: 'Mr. Chen', room: 'Rm 112', color: '#6d7cff', level: 'honors', goal: 90, cats: [k('Tests', 50), k('Quizzes', 25), k('Homework', 25)], sched: [{ days: [1, 2, 3, 4, 5], start: '09:00', end: '09:50' }], skill: 0.91 },
    { name: 'English 11', teacher: 'Mrs. Patel', room: 'Rm 230', color: '#f2b84b', level: 'regular', goal: 88, cats: [k('Essays', 40), k('Reading checks', 20), k('Participation', 10), k('Homework', 30)], sched: [{ days: [2, 4], start: '10:00', end: '11:20' }], skill: 0.89 },
    { name: 'US History', teacher: 'Mr. Brooks', room: 'Rm 118', color: '#f07178', level: 'regular', goal: 85, cats: [k('Tests', 45), k('Projects', 25), k('Homework', 30)], sched: [{ days: [1, 3, 5], start: '11:00', end: '11:50' }], skill: 0.82 },
    { name: 'Spanish 3', teacher: 'Sra. Gómez', room: 'Rm 305', color: '#38bdf8', level: 'regular', goal: 90, cats: [k('Tests', 40), k('Quizzes', 30), k('Homework', 30)], sched: [{ days: [2, 4], start: '13:00', end: '14:20' }], skill: 0.93 },
  ].map((c) => ({ id: uid('c'), name: c.name, teacher: c.teacher, room: c.room, color: c.color, level: c.level, credits: 1, goal: c.goal, gradingMode: 'weighted', categories: c.cats, schedule: c.sched, createdAt: Date.now(), skill: c.skill, ...demo }));
  const cat = (c, re) => c.categories.find((x) => re.test(x.name))?.id || c.categories[0].id;
  const A = [], add = (c, title, type, due, o = {}) => A.push({ id: uid('a'), classId: c.id, title, description: '', type, categoryId: o.cat || (type === 'other' ? cat(c, /particip|home/i) : cat(c, { homework: /home/i, quiz: /quiz|reading/i, test: /test/i, lab: /lab/i, essay: /essay/i, project: /project/i, reading: /reading/i }[type] || /home/i)), due, dueTime: o.time || '', priority: o.pri || 2, estMins: o.est ?? DEF_MINS[type], actualMins: null, status: 'not_started', score: null, max: null, attachments: [], createdAt: Date.now(), ...demo, ...o.extra });
  const [bio, alg, eng, his, spa] = C;
  // Past, graded work (last ~6 weeks). Scores come from a seeded generator around each class's level.
  const past = [[bio, ['Ch. 6 reading guide', 'homework', 20], ['Enzyme lab', 'lab', 50], ['Cell structure quiz', 'quiz', 30], ['Membrane transport worksheet', 'homework', 20], ['Unit 2 test', 'test', 100], ['Osmosis lab', 'lab', 50], ['Photosynthesis quiz', 'quiz', 30]],
    [alg, ['3.2 problem set', 'homework', 20], ['3.4 problem set', 'homework', 20], ['Quadratics quiz', 'quiz', 40], ['Unit 3 test', 'test', 100], ['4.1 problem set', 'homework', 20], ['Polynomials quiz', 'quiz', 40], ['4.3 problem set', 'homework', 20]],
    [eng, ['Gatsby ch. 1-3 reading check', 'reading', 20], ['Rhetorical analysis essay', 'essay', 100], ['Socratic seminar', 'other', 20], ['Vocab set 4', 'homework', 25], ['Gatsby ch. 4-6 reading check', 'reading', 20], ['Vocab set 5', 'homework', 25]],
    [his, ['Ch. 5 notes', 'homework', 25], ['Constitution DBQ', 'project', 100], ['Ch. 6 notes', 'homework', 25], ['Unit 3 test', 'test', 100], ['Ch. 7 notes', 'homework', 25]],
    [spa, ['Preterite practice', 'homework', 20], ['Vocab quiz 3A', 'quiz', 30], ['Imperfect workbook', 'homework', 20], ['Unidad 2 test', 'test', 100], ['Vocab quiz 3B', 'quiz', 30]]];
  for (const [c, ...items] of past) items.forEach(([title, type, max], i) => {
    const due = D(-40 + Math.round((i * 36) / items.length)), pct = clamp(c.skill + (rnd() - 0.45) * (type === 'test' ? 0.2 : 0.14) + (type === 'homework' ? 0.06 : 0), 0.55, 1);
    const late = rnd() < 0.12;
    add(c, title, type, due, { extra: { status: 'submitted', score: Math.round(pct * max * 2) / 2, max, gradedOn: D(-38 + Math.round((i * 36) / items.length)), completedAt: parseIso(late ? addDays(due, 1) : addDays(due, -1)).getTime(), submittedAt: parseIso(due).getTime(), actualMins: Math.round((DEF_MINS[type] * (0.9 + rnd() * 0.7)) / 5) * 5 } });
  });
  // Open and upcoming work
  add(his, 'Ch. 8 notes', 'homework', D(-2), { est: 40 });
  add(bio, 'Cellular respiration worksheet', 'homework', D(0), { est: 35, time: '23:59' });
  add(alg, '4.5 problem set', 'homework', D(1), { est: 40 });
  add(eng, 'Gatsby ch. 7-9 reading check', 'reading', D(1), { est: 60 });
  add(bio, 'Fermentation lab report', 'lab', D(2), { est: 90, pri: 3, extra: { status: 'in_progress', description: 'Write up the yeast fermentation lab: hypothesis, data table of CO₂ volume at 3 temperatures, graph, and a conclusion that explains the trend.' } });
  add(spa, 'Workbook p. 84-86', 'homework', D(2), { est: 30 });
  add(his, 'Progressive Era project', 'project', D(6), { est: 240, pri: 3, extra: { status: 'in_progress', steps: [{ id: uid('s'), title: 'Pick a reform and find 3 primary sources', mins: 60, done: true }, { id: uid('s'), title: 'Outline the slides', mins: 30, done: true }, { id: uid('s'), title: 'Build slides 1-5', mins: 60, done: false }, { id: uid('s'), title: 'Build slides 6-10', mins: 60, done: false }, { id: uid('s'), title: 'Rehearse and submit', mins: 30, done: false }], description: 'Slides (8-10) on one Progressive Era reform. Include 3 primary sources.' } });
  add(eng, 'Gatsby final essay', 'essay', D(9), { est: 180, pri: 3 });
  add(alg, '4.6 problem set', 'homework', D(4), { est: 40 });
  A.push({ ...A.find((a) => a.title === '4.5 problem set'), id: uid('a'), title: 'Daily warm-up', due: D(0), type: 'homework', estMins: 10, recur: { days: [1, 2, 3, 4, 5], until: D(30) } });
  // Exams
  const E = [
    { classId: bio.id, title: 'Unit 3 test: Cell energy', date: D(5), time: '08:00', categoryId: cat(bio, /test/i), topics: [['Photosynthesis', 4], ['Cellular respiration', 2], ['Fermentation', 3], ['Enzymes', 4], ['ATP', 3]] },
    { classId: alg.id, title: 'Unit 4 test: Polynomials', date: D(11), time: '09:00', categoryId: cat(alg, /test/i), topics: [['Polynomial division', 3], ['Factor theorem', 2], ['Graphing', 4]] },
    { classId: spa.id, title: 'Vocab quiz 3C', date: D(3), time: '13:00', categoryId: cat(spa, /quiz/i), max: 30, topics: [['Travel vocabulary', 3], ['Preterite vs. imperfect', 2]] },
  ].map((e) => ({ id: uid('e'), classId: e.classId, title: e.title, date: e.date, time: e.time, categoryId: e.categoryId, score: null, max: e.max || 100, topics: e.topics.map(([name, confidence]) => ({ id: uid('t'), name, confidence })), checklist: [{ id: uid('c'), text: 'Review all class notes', done: true }, { id: uid('c'), text: 'Do a full practice test', done: false }, { id: uid('c'), text: 'Pack supplies the night before', done: false }], plan: [], createdAt: Date.now(), ...demo }));
  // Decks with accurate content
  const decks = [], cards = [];
  const deck = (c, name, pairs) => { const d = { id: uid('k'), name, classId: c.id, createdAt: Date.now(), ...demo }; decks.push(d); pairs.forEach(([f, b], i) => { const st = i % 4; cards.push({ id: uid('f'), deckId: d.id, front: f, back: b, createdAt: Date.now(), ...(st === 0 ? {} : st === 1 ? { reps: 1, interval: 1, ease: 2.36, due: t, last: D(-1), lapses: 1 } : st === 2 ? { reps: 3, interval: 8, ease: 2.6, due: D(5), last: D(-3) } : { reps: 2, interval: 6, ease: 2.5, due: D(2), last: D(-4) }), ...demo }); }); return d; };
  deck(bio, 'Cell energy', [['ATP', 'Adenosine triphosphate, the molecule cells use to store and transfer energy'], ['Glycolysis', 'First stage of cellular respiration; splits glucose into two pyruvate in the cytoplasm, making 2 ATP'], ['Krebs cycle', 'Stage of aerobic respiration in the mitochondrial matrix that releases CO₂ and makes NADH and FADH₂'], ['Electron transport chain', 'Series of proteins in the inner mitochondrial membrane that uses NADH and FADH₂ to make most of the ATP'], ['Chlorophyll', 'Green pigment in chloroplasts that absorbs light energy for photosynthesis'], ['Calvin cycle', 'Light-independent reactions in the stroma that use ATP and NADPH to fix CO₂ into sugar'], ['Fermentation', 'Anaerobic process that regenerates NAD⁺ so glycolysis can continue without oxygen'], ['Enzyme', 'Protein that speeds up a reaction by lowering its activation energy'], ['Active site', 'Region of an enzyme where the substrate binds'], ['Denaturation', 'Loss of a protein’s shape (and function) from heat, pH or salt changes'], ['Stomata', 'Pores in leaves that let CO₂ in and O₂ and water vapor out'], ['Aerobic', 'Requiring oxygen']]);
  deck(spa, 'Unidad 3: viajes', [['el andén', 'the train platform'], ['la maleta', 'the suitcase'], ['el boleto de ida y vuelta', 'the round-trip ticket'], ['facturar el equipaje', 'to check luggage'], ['la aduana', 'customs'], ['el pasillo', 'the aisle'], ['aterrizar', 'to land'], ['despegar', 'to take off'], ['el horario', 'the schedule'], ['el asiento', 'the seat']]);
  deck(his, 'Constitution & government', [['Federalism', 'Division of power between the national government and the states'], ['Separation of powers', 'Splitting government into legislative, executive and judicial branches'], ['Checks and balances', 'Each branch can limit the powers of the others'], ['Bill of Rights', 'The first ten amendments to the Constitution, ratified in 1791'], ['Great Compromise', 'Agreement creating a House based on population and a Senate with two members per state'], ['Judicial review', 'Power of courts to strike down laws that conflict with the Constitution, established in Marbury v. Madison (1803)'], ['Anti-Federalists', 'Opponents of the Constitution who wanted stronger state power and a bill of rights'], ['Popular sovereignty', 'The idea that government gets its authority from the people']]);
  const notes = [{ id: uid('n'), classId: bio.id, title: 'Cellular respiration notes', topic: 'Unit 3', createdAt: Date.now(), updatedAt: Date.now() - 864e5, ...demo,
    body: `CELLULAR RESPIRATION\nCellular respiration is the process cells use to release energy stored in glucose. The overall equation is C6H12O6 + 6O2 → 6CO2 + 6H2O + ATP. It happens in three stages.\n\nGlycolysis\nGlycolysis: the breakdown of one glucose into two pyruvate molecules in the cytoplasm.\nIt does not need oxygen and makes a net gain of 2 ATP and 2 NADH.\n\nKrebs Cycle\nKrebs cycle: a series of reactions in the mitochondrial matrix that breaks pyruvate down into carbon dioxide.\nEach turn makes NADH, FADH2 and 1 ATP. The carbon dioxide we exhale comes from this stage.\n\nElectron Transport Chain\nThe electron transport chain is a group of proteins in the inner mitochondrial membrane. It uses electrons from NADH and FADH2 to pump hydrogen ions. ATP synthase uses the flow of hydrogen ions back across the membrane to make about 32-34 ATP. Oxygen is the final electron acceptor, which is why we need to breathe.\n\nFermentation\nFermentation is an anaerobic pathway that lets glycolysis keep going without oxygen. Lactic acid fermentation happens in muscle cells during hard exercise. Alcoholic fermentation happens in yeast and produces ethanol and CO2. Fermentation only makes 2 ATP per glucose, which is much less than aerobic respiration.` }];
  const sessions = []; const topics = { [bio.id]: ['Cellular respiration review', 'Photosynthesis notes', 'Enzymes practice', 'Fermentation lab report'], [alg.id]: ['Polynomial division practice', 'Graphing problems', 'Test corrections'], [eng.id]: ['Gatsby reading', 'Essay outline'], [his.id]: ['Chapter notes', 'Project research'], [spa.id]: ['Travel vocabulary', 'Preterite vs. imperfect drills'] };
  for (let i = 42; i >= 1; i--) { if (rnd() < 0.22) continue; const n = rnd() < 0.35 ? 2 : 1; for (let j = 0; j < n; j++) { const c = C[Math.floor(rnd() * C.length)], h = rnd() < 0.2 ? 7 : rnd() < 0.5 ? 16 : 19; const st = parseIso(D(-i)); st.setHours(h, Math.floor(rnd() * 4) * 15, 0, 0); sessions.push({ id: uid('s'), classId: c.id, topic: topics[c.id][Math.floor(rnd() * topics[c.id].length)], start: st.getTime(), mins: [25, 25, 30, 45, 50, 60][Math.floor(rnd() * 6)], rating: 2 + Math.floor(rnd() * 4) - (h === 19 && rnd() < 0.4 ? 1 : 0), mode: 'pomodoro', ...demo }); } }
  const results = [[bio, 'Cell energy', 7, 10, 18], [spa, 'Unidad 3: viajes', 8, 10, 12], [his, 'Constitution & government', 6, 8, 9], [bio, 'Cell energy', 9, 12, 4], [spa, 'Unidad 3: viajes', 9, 10, 2]].map(([c, title, cor, tot, ago]) => ({ id: uid('r'), title, classId: c.id, deckIds: [decks.find((d) => d.name === title).id], kind: ago === 4 ? 'test' : 'quiz', exam: ago === 4, correct: cor, total: tot, mins: Math.round(tot * 0.8), at: parseIso(D(-ago)).getTime() + 17 * 36e5, ...demo }));
  const events = [{ id: uid('v'), title: 'Basketball practice', date: weekStart(D(-21)), start: '15:30', end: '17:30', allDay: false, kind: 'activity', classId: '', color: EV_KINDS.activity[1], weekly: true, until: '', notes: '', ...demo },
    { id: uid('v'), title: 'Basketball practice', date: addDays(weekStart(D(-21)), 2), start: '15:30', end: '17:30', allDay: false, kind: 'activity', classId: '', color: EV_KINDS.activity[1], weekly: true, until: '', notes: '', ...demo },
    { id: uid('v'), title: 'Study group: Bio', date: D(3), start: '17:00', end: '18:00', allDay: false, kind: 'study', classId: bio.id, color: '', weekly: false, until: '', notes: 'Library room B', ...demo }];
  S.classes.push(...C.map(({ skill, ...c }) => c)); S.assignments.push(...A); S.decks.push(...decks); S.cards.push(...cards); S.notes.push(...notes); S.sessions.push(...sessions); S.results.push(...results); S.events.push(...events); S.exams.push(...E);
  for (const e of S.exams.filter((x) => x.demo)) e.plan = buildExamPlan(e, e.title.startsWith('Unit 3') ? { from: D(-4) } : {}).map((p) => ({ ...p, done: p.date < t }));
  const bp = S.exams.find((x) => x.demo && x.title.startsWith('Unit 3')).plan; if (bp[0]) bp[0].done = false; // one missed session to show catching up
  // Topics (exam topics are created automatically; these add units and topics without exams), linked to cards
  ensureTopics();
  const T = (c, name, unit) => { let t = topicByName(c.id, name); if (!t) { t = { id: uid('tp'), classId: c.id, name, unit, createdAt: Date.now(), demo: true }; S.topics.push(t); } t.unit = unit; t.demo = true; return t; };
  const bt = { atp: T(bio, 'ATP', 'Unit 3: Cell energy'), resp: T(bio, 'Cellular respiration', 'Unit 3: Cell energy'), ferm: T(bio, 'Fermentation', 'Unit 3: Cell energy'), photo: T(bio, 'Photosynthesis', 'Unit 3: Cell energy'), enz: T(bio, 'Enzymes', 'Unit 2: Cells'), memb: T(bio, 'Membrane transport', 'Unit 2: Cells') };
  T(alg, 'Polynomial division', 'Unit 4: Polynomials'); T(alg, 'Factor theorem', 'Unit 4: Polynomials'); T(alg, 'Graphing', 'Unit 4: Polynomials'); T(alg, 'Quadratics', 'Unit 3: Quadratics');
  const travel = T(spa, 'Travel vocabulary', 'Unidad 3'); T(spa, 'Preterite vs. imperfect', 'Unidad 3'); const consti = T(his, 'Constitution', 'Unit 3: Founding'); T(his, 'Progressive Era', 'Unit 5');
  const bioMap = { ATP: bt.atp, Glycolysis: bt.resp, 'Krebs cycle': bt.resp, 'Electron transport chain': bt.resp, Aerobic: bt.resp, Chlorophyll: bt.photo, 'Calvin cycle': bt.photo, Stomata: bt.photo, Fermentation: bt.ferm, Enzyme: bt.enz, 'Active site': bt.enz, Denaturation: bt.enz };
  for (const c of cards) { const dk = decks.find((d) => d.id === c.deckId); if (dk.classId === bio.id) c.topicId = bioMap[c.front]?.id; }
  decks.find((d) => d.classId === spa.id).topicId = travel.id; decks.find((d) => d.classId === his.id).topicId = consti.id;
  // Per-question results for the sample quizzes (cards with lapses were missed more often)
  for (const r of results) { const cs = cards.filter((c) => r.deckIds.includes(c.deckId)).slice(0, r.total); let need = r.correct; r.cardResults = cs.map((c, i) => { const miss = (c.lapses || c.front === 'Krebs cycle') && cs.length - i > need; const ok = !miss && need > 0; if (ok) need--; return { id: c.id, s: ok ? 1 : 0 }; }); r.correct = sum(r.cardResults.map((x) => x.s)); r.total = r.cardResults.length; }
  // Goals (baseline recorded now)
  for (const g of [{ type: 'class_grade', classId: bio.id, target: 90 }, { type: 'study_hours', target: 6 }, { type: 'quiz_accuracy', target: 85 }, { type: 'master_topics', classId: bio.id, topicIds: [bt.atp.id, bt.resp.id, bt.photo.id] }]) { const goal = { id: uid('gl'), weighted: false, topicIds: [], deadline: g.type === 'class_grade' ? D(30) : '', createdAt: Date.now() - 10 * 864e5, demo: true, ...g }; if (g.type === 'master_topics') goal.target = g.topicIds.length; goal.start = goalBaseline(goal); S.goals.push(goal); }
  S.settings.demo = true; if (!S.profile.name) { S.profile.name = 'Alex Student'; S.profile.grade = '11th grade'; S.profile.term = 'Fall semester'; S.profile.demo = true; }
  expandRecurring(); refreshOverdue();
  save('profile', 'settings', ...COLLECTIONS); toast('Sample semester loaded. Remove it any time in Settings.'); go('home');
}
async function clearSample() {
  if (!(await confirmBox('Remove all sample data? Your own records stay.', 'Remove sample', true))) return;
  for (const c of COLLECTIONS) S[c] = S[c].filter((x) => !x.demo);
  const ids = new Set(S.decks.map((d) => d.id)); S.cards = S.cards.filter((c) => ids.has(c.deckId)); const cids = new Set(S.classes.map((c) => c.id)); S.topics = S.topics.filter((t) => cids.has(t.classId)); S.goals = S.goals.filter((g) => !g.classId || cids.has(g.classId)); S.snapshots = [];
  if (S.profile.demo) S.profile = DEFAULT_PROFILE(); S.settings.demo = false;
  save('profile', 'settings', ...COLLECTIONS); toast('Sample data removed'); go('home');
}
